ilJob>();s.AddScoped<ILearnerIdentityService,LearnerIdentityService>();s.AddScoped<ILearnerConsentService,LearnerConsentService>();s.AddScoped<IAdmissionApplicationService,AdmissionApplicationService>();s.AddScoped<IPublicAdmissionService,PublicAdmissionService>();s.AddScoped<IAdmissionEnrollmentService,AdmissionEnrollmentService>();s.AddScoped<IAdmissionAssessmentService,AdmissionAssessmentService>();s.AddScoped<IStudentDirectoryService,StudentDirectoryService>();s.AddScoped<IStudentPromotionService,StudentPromotionService>();s.AddScoped<IStudentExitService,StudentExitService>();s.AddScoped<IStudentAttendanceService,StudentAttendanceService>();s.AddScoped<IExamWorkflowService,ExamWorkflowService>();s.AddScoped<IFeeBillingService,FeeBillingService>();s.AddScoped<ISelfServicePortalService,SelfServicePortalService>();s.AddScoped<ILmsWorkflowService,LmsWorkflowService>();s.AddScoped<IHrPayrollService,HrPayrollService>();s.AddScoped<ILibraryService,LibraryService>();return s;}}}
